/**
 * Creates an authentic 10-cup Solo Cup pyramid layout.
 * Rows:
 * Row 1 (front): 1 cup (id 1)
 * Row 2: 2 cups (id 2, 3)
 * Row 3: 3 cups (id 4, 5, 6)
 * Row 4 (back): 4 cups (id 7, 8, 9, 10)
 */
function createPyramidLayout(): CupData[] {
  const cups: CupData[] = [];
  let idCounter = 1;

  // Row 1: 1 cup at apex (relative Z = -0.5 on the runway)
  cups.push({
    id: idCounter++,
    row: 1,
    col: 1,
    relX: 0,
    relZ: -0.5,
    worldPos: new THREE.Vector3(),
    isSunk: false,
    sinkAnimProgress: 0,
  });

  // Row 2: 2 cups
  [-0.5, 0.5].forEach((offset, colIdx) => {
    cups.push({
      id: idCounter++,
      row: 2,
      col: colIdx + 1,
      relX: offset * CUP_SPACING_X,
      relZ: -0.5 + CUP_SPACING_Z,
      worldPos: new THREE.Vector3(),
      isSunk: false,
      sinkAnimProgress: 0,
    });
  });

  // Row 3: 3 cups
  [-1.0, 0.0, 1.0].forEach((offset, colIdx) => {
    cups.push({
      id: idCounter++,
      row: 3,
      col: colIdx + 1,
      relX: offset * CUP_SPACING_X,
      relZ: -0.5 + CUP_SPACING_Z * 2,
      worldPos: new THREE.Vector3(),
      isSunk: false,
      sinkAnimProgress: 0,
    });
  });

  // Row 4: 4 cups
  [-1.5, -0.5, 0.5, 1.5].forEach((offset, colIdx) => {
    cups.push({
      id: idCounter++,
      row: 4,
      col: colIdx + 1,
      relX: offset * CUP_SPACING_X,
      relZ: -0.5 + CUP_SPACING_Z * 3,
      worldPos: new THREE.Vector3(),
      isSunk: false,
      sinkAnimProgress: 0,
    });
  });

  return cups;
}

/**
 * Builds an authentic, giant Solo Cup flush-mounted into the tournament runway deck.
 * Features:
 * - Rounded rolled white lip torus resting on table deck (Y = 0)
 * - Tapered cup body hanging downward beneath the acrylic glass
 * - White inner lining and sealed bottom disc (no grass visible through cup)
 * - Molded horizontal grip ridges
 * - Glistening golden amber beer liquid disk with creamy white foam ring and head bubbles
 * - Glowing target halo ring
 */
function buildSoloCupMesh(team: 'red' | 'blue' = 'red'): CupMeshReference {
  const group = new THREE.Group();
  const primaryColor = team === 'red' ? 0xee2020 : 0x2563eb;

  // 1. Rolled Lip Rim resting on table level (Y = 0.01)
  const rimGeo = new THREE.TorusGeometry(CUP_TOP_RADIUS, 0.034, 16, 48);
  rimGeo.rotateX(Math.PI / 2);
  const rimMat = new THREE.MeshStandardMaterial({
    color: 0xffffff,
    roughness: 0.2,
    metalness: 0.1,
  });
  const rimRingMesh = new THREE.Mesh(rimGeo, rimMat);
  rimRingMesh.position.y = 0.01;
  group.add(rimRingMesh);

  // 2. Open-Ended Tapered Solo Cup Cylinder (openEnded = TRUE: NO TOP CAP, NO LID)
  const cupGeo = new THREE.CylinderGeometry(
    CUP_TOP_RADIUS,
    CUP_BOTTOM_RADIUS,
    CUP_HEIGHT,
    48,
    1,
    true // openEnded = true! Completely open top and bottom
  );
  const cupMaterial = new THREE.MeshStandardMaterial({
    color: primaryColor,
    roughness: 0.35,
    metalness: 0.08,
    side: THREE.DoubleSide,
  });
  const outerMesh = new THREE.Mesh(cupGeo, cupMaterial);
  outerMesh.position.y = -CUP_HEIGHT / 2;
  outerMesh.receiveShadow = true;
  group.add(outerMesh);

  // 3. Sealed Bottom Disc (closed base plate inside the bottom of the cup)
  const bottomGeo = new THREE.CircleGeometry(CUP_BOTTOM_RADIUS - 0.002, 36);
  bottomGeo.rotateX(-Math.PI / 2);
  const bottomMat = new THREE.MeshStandardMaterial({
    color: primaryColor,
    roughness: 0.4,
    side: THREE.DoubleSide,
  });
  const bottomMesh = new THREE.Mesh(bottomGeo, bottomMat);
  bottomMesh.position.y = -CUP_HEIGHT + 0.008;
  group.add(bottomMesh);

  // 4. Iconic Solo Cup Horizontal Grip Ridges
  [-0.12, -0.22, -0.32].forEach((h) => {
    const fraction = -h / CUP_HEIGHT;
    const r = CUP_TOP_RADIUS - (CUP_TOP_RADIUS - CUP_BOTTOM_RADIUS) * fraction;
    const ridgeGeo = new THREE.TorusGeometry(r + 0.006, 0.012, 12, 36);
    ridgeGeo.rotateX(Math.PI / 2);
    const ridgeMesh = new THREE.Mesh(ridgeGeo, cupMaterial);
    ridgeMesh.position.y = h;
    group.add(ridgeMesh);
  });

  // 5. Glistening Golden Amber Beer Liquid (sits 7cm below top rim)
  const liquidY = -0.07;
  const liquidFrac = 0.07 / CUP_HEIGHT;
  const liquidR = CUP_TOP_RADIUS - (CUP_TOP_RADIUS - CUP_BOTTOM_RADIUS) * liquidFrac - 0.008;
  const liquidGeo = new THREE.CircleGeometry(liquidR, 48);
  liquidGeo.rotateX(-Math.PI / 2);
  const liquidMat = new THREE.MeshStandardMaterial({
    color: 0xf59e0b, // Warm sparkling golden beer
    roughness: 0.08,
    metalness: 0.15,
    emissive: 0xd97706,
    emissiveIntensity: 0.45,
    side: THREE.DoubleSide,
  });
  ctx.liquidMaterials.push(liquidMat);
  const liquidMesh = new THREE.Mesh(liquidGeo, liquidMat);
  liquidMesh.position.y = liquidY;
  group.add(liquidMesh);

  // 6. Creamy White Beer Foam Ring around edge
  const foamGeo = new THREE.RingGeometry(liquidR - 0.065, liquidR, 48);
  foamGeo.rotateX(-Math.PI / 2);
  const foamMat = new THREE.MeshBasicMaterial({
    color: 0xfffef0,
    side: THREE.DoubleSide,
  });
  const foamMesh = new THREE.Mesh(foamGeo, foamMat);
  foamMesh.position.y = liquidY + 0.002;
  group.add(foamMesh);

  // 7. Surface Foam Bubbles
  [
    { x: 0.14, z: 0.12, r: 0.035 },
    { x: -0.18, z: 0.08, r: 0.04 },
    { x: -0.05, z: -0.16, r: 0.032 },
    { x: 0.16, z: -0.14, r: 0.028 },
  ].forEach((f) => {
    const bubbleGeo = new THREE.CircleGeometry(f.r, 16);
    bubbleGeo.rotateX(-Math.PI / 2);
    const bubbleMesh = new THREE.Mesh(bubbleGeo, foamMat);
    bubbleMesh.position.set(f.x, liquidY + 0.003, f.z);
    group.add(bubbleMesh);
  });

  // 8. Glowing Target Aura Ring
  const haloGeo = new THREE.RingGeometry(CUP_TOP_RADIUS + 0.04, CUP_TOP_RADIUS + 0.20, 48);
  haloGeo.rotateX(-Math.PI / 2);
  const haloMat = new THREE.MeshBasicMaterial({
    color: 0xf59e0b,
    transparent: true,
    opacity: 0.0,
    side: THREE.DoubleSide,
  });
  const haloMesh = new THREE.Mesh(haloGeo, haloMat);
  haloMesh.position.y = 0.012;
  group.add(haloMesh);

  return {
    group,
    outerMesh,
    innerMesh: bottomMesh,
    rimRingMesh,
    liquidMesh,
    foamMesh,
    haloMesh,
    cupMaterial,
  };
}

/**
 * Generates a contiguous tournament table deck geometry that spans the entire table
 * and features precision circular cutouts for all active solo cups.
 * This holds the cups flush with the deck so balls can roll across and drop in cleanly.
 */
function createTableDeckGeometry(
  tableWidth: number,
  tableLength: number,
  cups: CupData[],
  scale: number
): THREE.BufferGeometry {
  const shape = new THREE.Shape();
  const halfW = tableWidth / 2;
  const halfL = tableLength / 2;

  // Counter-Clockwise outer rectangle in 2D (X, Y)
  // When rotated by -PI/2 around X:
  // 3D X = 2D X, 3D Y = 0, 3D Z = -2D Y
  // Top-Left (-halfW, halfL) -> Top-Right (halfW, halfL) -> Bottom-Right (halfW, -halfL) -> Bottom-Left (-halfW, -halfL)
  shape.moveTo(-halfW, halfL);
  shape.lineTo(halfW, halfL);
  shape.lineTo(halfW, -halfL);
  shape.lineTo(-halfW, -halfL);
  shape.closePath();

  // Hole radius: precision circular cutout matching the cup rim
  const holeRadius = (CUP_TOP_RADIUS - 0.015) * scale;

  cups.forEach((cup) => {
    if (cup.isSunk) return;
    const holePath = new THREE.Path();
    holePath.absarc(
      cup.relX * scale,
      -cup.relZ * scale,
      holeRadius,
      0,
      Math.PI * 2,
      true
    );
    shape.holes.push(holePath);
  });

  const geo = new THREE.ShapeGeometry(shape, 32);
  geo.rotateX(-Math.PI / 2);
  geo.computeVertexNormals();
  return geo;
}

/**
 * Builds the illuminated transparent tournament runway
 * with roll-up approach ramp, glowing neon cyan/amber edge trim, and underglow.
 */
function buildBeerPongTable(): {
  tableGroup: THREE.Group;
  tableTop: THREE.Mesh;
  tableRamp: THREE.Mesh;
  borders: THREE.Mesh[];
  centerLine: THREE.Mesh;
  legsGroup: THREE.Group;
} {
  const tableGroup = new THREE.Group();

  // 1. Seamless Tournament Table Deck holding all cups flush (spans full length Z: -TABLE_LENGTH/2 to +TABLE_LENGTH/2)
  const initialRack = createPyramidLayout();
  const topGeo = createTableDeckGeometry(TABLE_WIDTH, TABLE_LENGTH, initialRack, 1.0);
  const tableTex = getProceduralTableTexture();
  tableTex.repeat.set(6, 12);
  const topMat = new THREE.MeshStandardMaterial({
    map: tableTex,
    color: 0x1e293b,
    transparent: true,
    opacity: 0.92,
    roughness: 0.12,
    metalness: 0.35,
    side: THREE.DoubleSide,
  });
  const tableTop = new THREE.Mesh(topGeo, topMat);
  tableTop.position.set(0, TABLE_HEIGHT, 0);
  tableTop.castShadow = true;
  tableTop.receiveShadow = true;
  tableTop.userData.surface = 'fairway'; // enables ball bounces & roll-in
  tableGroup.add(tableTop);

  // 2. Beveled Leading Edge Roll-Up Ramp at front of table (slopes from Y = 0 to Y = TABLE_HEIGHT)
  const rampLength = 3.0;
  const rampGeo = new THREE.BoxGeometry(TABLE_WIDTH, 0.04, rampLength);
  const rampMat = new THREE.MeshStandardMaterial({
    color: 0x1e293b,
    roughness: 0.35,
    metalness: 0.1,
  });
  const tableRamp = new THREE.Mesh(rampGeo, rampMat);
  tableRamp.position.set(0, TABLE_HEIGHT / 4, -TABLE_LENGTH / 2 - rampLength / 2);
  tableRamp.rotation.x = Math.atan2(TABLE_HEIGHT, rampLength);
  tableRamp.userData.surface = 'fairway';
  tableGroup.add(tableRamp);

  // 3. Platform base floor underneath the cups (low level at Y = 0.02)
  const baseFloorGeo = new THREE.BoxGeometry(TABLE_WIDTH, 0.04, TABLE_LENGTH / 2 + 0.7);
  const baseFloorMat = new THREE.MeshStandardMaterial({
    color: 0x090d16,
    roughness: 0.6,
  });
  const baseFloor = new THREE.Mesh(baseFloorGeo, baseFloorMat);
  baseFloor.position.set(0, 0.02, TABLE_LENGTH / 4 + 0.35);
  tableGroup.add(baseFloor);

  // 4. Glowing Neon Edge Trim along sides & back
  const borderMat = new THREE.MeshBasicMaterial({ color: 0x38bdf8 }); // Cyan neon edge
  const borders: THREE.Mesh[] = [];

  // Left neon stripe
  const leftStripeGeo = new THREE.BoxGeometry(0.08, 0.06, TABLE_LENGTH);
  const leftStripe = new THREE.Mesh(leftStripeGeo, borderMat);
  leftStripe.position.set(-TABLE_WIDTH / 2, TABLE_HEIGHT + 0.03, 0);
  tableGroup.add(leftStripe);
  borders.push(leftStripe);

  // Right neon stripe
  const rightStripe = leftStripe.clone();
  rightStripe.position.x = TABLE_WIDTH / 2;
  tableGroup.add(rightStripe);
  borders.push(rightStripe);

  // Back neon bumper
  const backStripeGeo = new THREE.BoxGeometry(TABLE_WIDTH, 0.08, 0.08);
  const backStripe = new THREE.Mesh(backStripeGeo, borderMat);
  backStripe.position.set(0, TABLE_HEIGHT + 0.04, TABLE_LENGTH / 2);
  tableGroup.add(backStripe);
  borders.push(backStripe);

  // 5. Center Divider & Aim Line on Runway (runs up to head pin cup at Z = 0)
  const runwayLength = TABLE_LENGTH / 2;
  const runwayCenterZ = -TABLE_LENGTH / 4;
  const lineMat = new THREE.MeshBasicMaterial({ color: 0xf59e0b, transparent: true, opacity: 0.75 });
  const centerLineGeo = new THREE.PlaneGeometry(0.08, runwayLength);
  centerLineGeo.rotateX(-Math.PI / 2);
  const centerLine = new THREE.Mesh(centerLineGeo, lineMat);
  centerLine.position.set(0, TABLE_HEIGHT + 0.002, runwayCenterZ);
  tableGroup.add(centerLine);

  // 6. Sturdy Tournament Platform Legs / Podium Skirt
  const legsGroup = new THREE.Group();
  const legMat = new THREE.MeshStandardMaterial({ color: 0x090d16, roughness: 0.6 });
  [-TABLE_WIDTH / 2 + 0.3, TABLE_WIDTH / 2 - 0.3].forEach((lx) => {
    [-TABLE_LENGTH / 2 + 0.6, 0, TABLE_LENGTH / 2 - 0.6].forEach((lz) => {
      const legGeo = new THREE.CylinderGeometry(0.12, 0.16, TABLE_HEIGHT - 0.06, 16);
      const legMesh = new THREE.Mesh(legGeo, legMat);
      legMesh.position.set(lx, (TABLE_HEIGHT - 0.06) / 2, lz);
      legsGroup.add(legMesh);
    });
  });
  tableGroup.add(legsGroup);

  // 7. Ambient Deck Underglow PointLights
  [-TABLE_WIDTH / 3, TABLE_WIDTH / 3].forEach((x) => {
    [-TABLE_LENGTH / 4, TABLE_LENGTH / 4].forEach((z) => {
      const underglow = new THREE.PointLight(0xf59e0b, 2.8, 10);
      underglow.position.set(x, TABLE_HEIGHT / 2, z);
      tableGroup.add(underglow);
    });
  });

  return { tableGroup, tableTop, tableRamp, borders, centerLine, legsGroup };
}

