function initParticleSystem(scene: THREE.Scene) {
  const maxParticles = 300;
  const positions = new Float32Array(maxParticles * 3);
  const colors = new Float32Array(maxParticles * 3);

  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));

  const mat = new THREE.PointsMaterial({
    size: 0.09,
    vertexColors: true,
    transparent: true,
    opacity: 0.95,
    blending: THREE.AdditiveBlending,
  });

  const points = new THREE.Points(geo, mat);
  points.frustumCulled = false;
  scene.add(points);

  ctx.particlePoints = points;
  ctx.particleGeo = geo;
}

function spawnSplashParticles(centerPos: THREE.Vector3) {
  const count = 50;
  const amberColor = new THREE.Color(0xf59e0b);
  const foamColor = new THREE.Color(0xfffef0);

  for (let i = 0; i < count; i++) {
    const isFoam = Math.random() > 0.55;
    const angle = Math.random() * Math.PI * 2;
    const speed = 1.4 + Math.random() * 3.2;
    const upwardVel = 2.8 + Math.random() * 4.0;

    ctx.splashParticles.push({
      pos: centerPos.clone().add(new THREE.Vector3(
        (Math.random() - 0.5) * 0.3,
        0.1,
        (Math.random() - 0.5) * 0.3
      )),
      vel: new THREE.Vector3(
        Math.cos(angle) * speed,
        upwardVel,
        Math.sin(angle) * speed
      ),
      color: isFoam ? foamColor.clone() : amberColor.clone(),
      size: 0.05 + Math.random() * 0.07,
      life: 0,
      maxLife: 0.85 + Math.random() * 0.55,
    });
  }
}

function updateSplashParticles(delta: number) {
  if (!ctx.particleGeo) return;

  const positions = ctx.particleGeo.attributes.position.array as Float32Array;
  const colors = ctx.particleGeo.attributes.color.array as Float32Array;
  const gravity = -9.8;

  for (let i = ctx.splashParticles.length - 1; i >= 0; i--) {
    const p = ctx.splashParticles[i];
    p.life += delta;
    if (p.life >= p.maxLife) {
      ctx.splashParticles.splice(i, 1);
      continue;
    }

    p.vel.y += gravity * delta;
    p.pos.addScaledVector(p.vel, delta);
  }

  // Update buffer geometry attributes
  let pIdx = 0;
  for (let i = 0; i < ctx.splashParticles.length && pIdx < 300; i++) {
    const p = ctx.splashParticles[i];
    const alpha = 1.0 - (p.life / p.maxLife);

    positions[pIdx * 3] = p.pos.x;
    positions[pIdx * 3 + 1] = p.pos.y;
    positions[pIdx * 3 + 2] = p.pos.z;

    colors[pIdx * 3] = p.color.r * alpha;
    colors[pIdx * 3 + 1] = p.color.g * alpha;
    colors[pIdx * 3 + 2] = p.color.b * alpha;

    pIdx++;
  }

  // Zero out remaining positions
  for (let i = pIdx; i < 300; i++) {
    positions[i * 3 + 1] = -100;
  }

  ctx.particleGeo.attributes.position.needsUpdate = true;
  ctx.particleGeo.attributes.color.needsUpdate = true;
}

