  scene.fog = null;

  // AAA Stadium Night Sky Dome with twinkling stars, horizon stadium glow, and procedural night sky
  ctx.atmosphere = createStadiumAtmosphere(scene, 420);

  // Large procedural fairway turf green spanning 320m wide x 550m long, centered at Z = 160m
  const groundGeo = new THREE.PlaneGeometry(320, 550, 48, 48);
  groundGeo.rotateX(-Math.PI / 2);
  const fairwayTextures = getProceduralFairwayTextures(8);
  fairwayTextures.map.repeat.set(36, 64);
