function positionTableAndCups(targetDistanceYards: number) {
  const distMeters = UnitConversions.yardsToMeters(targetDistanceYards);
  const scale = getScaleForDistance(targetDistanceYards);

  ctx.tableCenterPos.set(0, TABLE_HEIGHT / 2, distMeters);

  if (ctx.tableGroup) {
    ctx.tableGroup.position.set(0, 0, distMeters);
  }

  // Dynamically scale tournament table deck with precision cup cutout holes
  const tableWidth = TABLE_WIDTH * scale;
  const tableLength = TABLE_LENGTH * Math.min(scale, 4.0);

  if (ctx.tableTopMesh) {
    ctx.tableTopMesh.geometry.dispose();
    ctx.tableTopMesh.geometry = createTableDeckGeometry(tableWidth, tableLength, ctx.cups, scale);
    ctx.tableTopMesh.position.set(0, TABLE_HEIGHT, 0);
  }

  // Dynamically scale approach roll-up ramp
  const rampLength = 3.0 * Math.max(1, scale * 0.7);
  if (ctx.tableRampMesh) {
    ctx.tableRampMesh.geometry.dispose();
    ctx.tableRampMesh.geometry = new THREE.BoxGeometry(tableWidth, 0.04, rampLength);
    ctx.tableRampMesh.position.set(0, TABLE_HEIGHT / 4, -tableLength / 2 - rampLength / 2);
    ctx.tableRampMesh.rotation.x = Math.atan2(TABLE_HEIGHT, rampLength);
  }

  // Dynamically scale neon rails
  if (ctx.tableBorders.length >= 3) {
    ctx.tableBorders[0].geometry.dispose();
    ctx.tableBorders[0].geometry = new THREE.BoxGeometry(0.08, 0.06, tableLength);
    ctx.tableBorders[0].position.set(-tableWidth / 2, TABLE_HEIGHT + 0.03, 0);

    ctx.tableBorders[1].geometry.dispose();
    ctx.tableBorders[1].geometry = new THREE.BoxGeometry(0.08, 0.06, tableLength);
    ctx.tableBorders[1].position.set(tableWidth / 2, TABLE_HEIGHT + 0.03, 0);

    ctx.tableBorders[2].geometry.dispose();
    ctx.tableBorders[2].geometry = new THREE.BoxGeometry(tableWidth, 0.08, 0.08);
    ctx.tableBorders[2].position.set(0, TABLE_HEIGHT + 0.04, tableLength / 2);
  }

  if (ctx.tableCenterLine) {
    ctx.tableCenterLine.geometry.dispose();
    const runwayLength = tableLength / 2;
    const runwayCenterZ = -tableLength / 4;
    const clGeo = new THREE.PlaneGeometry(0.08, runwayLength);
    clGeo.rotateX(-Math.PI / 2);
    ctx.tableCenterLine.geometry = clGeo;
    ctx.tableCenterLine.position.set(0, TABLE_HEIGHT + 0.002, runwayCenterZ);
  }

  // CRITICAL FIX: Update world positions of BOTH redRack AND blueRack!
  const updateRack = (rack: CupData[]) => {
    rack.forEach((cup) => {
      cup.worldPos.set(
        cup.relX * scale,
        TABLE_HEIGHT,
        distMeters + cup.relZ * scale
      );
    });
  };

  updateRack(ctx.redRack);
  updateRack(ctx.blueRack);

  // Position 3D meshes to match currently active rack
  ctx.cups.forEach((cup, idx) => {
    const meshRef = ctx.cupMeshes[idx];
    if (meshRef) {
      meshRef.group.position.set(cup.relX * scale, TABLE_HEIGHT, cup.relZ * scale);
      meshRef.group.scale.set(scale, scale, scale);
      meshRef.group.visible = !cup.isSunk;
    }
  });

  // Re-build terrain collision map so table & ramp colliders update to new scale and distance
  if (ctx.golfBall && ctx.groundMesh && ctx.tableTopMesh && ctx.tableRampMesh) {
    ctx.golfBall.physics.buildTerrainMap([ctx.groundMesh, ctx.tableTopMesh, ctx.tableRampMesh]);
  }

  // Re-calculate target aim point to selected cup or head pin
  updateAimToSelectedCup();
}

function syncCupMeshesWithActiveRack() {
  const scale = getScaleForDistance(ctx.state.distanceYards);
  // In versus mode: Player 1 (Red) shoots at Blue Solo cups; Player 2 (Blue) shoots at Red Solo cups
  const isTargetBlue = (ctx.state.mode === 'versus' && ctx.state.activePlayerIndex === 0);
  const primaryColor = isTargetBlue ? 0x2563eb : 0xee2020;
  const haloColor = isTargetBlue ? 0x38bdf8 : 0xf59e0b;

  ctx.cupMeshes.forEach((meshRef, idx) => {
    const cup = ctx.cups[idx];
    if (!cup) return;

    cup.meshGroup = meshRef.group;
    cup.liquidMesh = meshRef.liquidMesh;
    cup.rimRingMesh = meshRef.rimRingMesh;
    cup.haloMesh = meshRef.haloMesh;

    meshRef.cupMaterial.color.setHex(primaryColor);
    (meshRef.haloMesh.material as THREE.MeshBasicMaterial).color.setHex(haloColor);

    meshRef.group.visible = !cup.isSunk;
    meshRef.group.scale.set(scale, scale, scale);
    meshRef.group.position.set(cup.relX * scale, TABLE_HEIGHT, cup.relZ * scale);
    meshRef.group.userData = { cupId: cup.id };

    if (!cup.isSunk) {
      meshRef.liquidMesh.position.y = -0.07;
      (meshRef.rimRingMesh.material as THREE.MeshStandardMaterial).opacity = 1.0;
      (meshRef.haloMesh.material as THREE.MeshBasicMaterial).opacity = (cup.id === ctx.state.selectedCupId) ? 0.8 : 0.0;
    }
  });
}

function updateAimToSelectedCup() {
  const selectedCup = ctx.cups.find((c) => c.id === ctx.state.selectedCupId && !c.isSunk)
    || ctx.cups.find((c) => !c.isSunk)
    || ctx.cups[0];

  if (selectedCup) {
    ctx.state.selectedCupId = selectedCup.id;

    // Safety fallback: if cup worldPos is not yet at distance, compute from distanceYards
    if (selectedCup.worldPos.z <= 1.0) {
      const distMeters = UnitConversions.yardsToMeters(ctx.state.distanceYards);
      const scale = getScaleForDistance(ctx.state.distanceYards);
      selectedCup.worldPos.set(selectedCup.relX * scale, TABLE_HEIGHT, distMeters + selectedCup.relZ * scale);
    }

    // Compute base cup angle and distance relative to tee (startPoint)
    const dx = selectedCup.worldPos.x - ctx.startPoint.x;
    const dz = selectedCup.worldPos.z - ctx.startPoint.z;
    const baseAngleRad = Math.atan2(dx, dz);
    const dist = Math.sqrt(dx * dx + dz * dz);

    // Total aim angle = base cup angle + aim nudge (tilt) angle
    const totalAngleRad = baseAngleRad + (ctx.state.aimAngleDeg * (Math.PI / 180));

    ctx.aimPoint.x = ctx.startPoint.x + Math.sin(totalAngleRad) * dist;
    ctx.aimPoint.y = TABLE_HEIGHT + CUP_HEIGHT;
    ctx.aimPoint.z = ctx.startPoint.z + Math.cos(totalAngleRad) * dist;

    if (ctx.golfBall) {
      ctx.golfBall.aimAt(ctx.aimPoint);
    }

    if (ctx.camera) {
      ctx.camera.setPositions(ctx.startPoint, ctx.aimPoint);
    }

    // Highlight target cup in 3D
    ctx.cupMeshes.forEach((meshRef, idx) => {
      const c = ctx.cups[idx];
      if (c && meshRef.haloMesh) {
        meshRef.haloMesh.material.opacity = (c.id === selectedCup.id && !c.isSunk) ? 0.8 : 0.0;
      }
    });

    const aimInfoEl = document.getElementById('target-aim-info');
    if (aimInfoEl) {
      const totalDeg = (totalAngleRad * 180 / Math.PI);
      const nudgeStr = Math.abs(ctx.state.aimAngleDeg) < 0.1 
        ? '' 
        : ` | Offset: ${ctx.state.aimAngleDeg > 0 ? '+' : ''}${ctx.state.aimAngleDeg.toFixed(1)}°`;
      aimInfoEl.textContent = `Target: Cup #${selectedCup.id} (Row ${selectedCup.row}) | Aim: ${totalDeg.toFixed(1)}°${nudgeStr}`;
    }
  }

  updateLaserTether();
  drawRackMinimap();
}

function updateLaserTether() {
  if (!ctx.laserLine) {
    const lineGeo = new THREE.BufferGeometry().setFromPoints([
      new THREE.Vector3(0, 0.05, 0),
      ctx.aimPoint,
    ]);
    const lineMat = new THREE.LineDashedMaterial({
      color: 0xf59e0b,
      dashSize: 0.6,
      gapSize: 0.4,
      transparent: true,
      opacity: 0.7,
    });
    ctx.laserLine = new THREE.Line(lineGeo, lineMat);
    ctx.laserLine.computeLineDistances();
    ctx.scene.add(ctx.laserLine);
  } else {
    ctx.laserLine.geometry.setFromPoints([
      new THREE.Vector3(0, 0.05, 0),
      ctx.aimPoint,
    ]);
    ctx.laserLine.computeLineDistances();
  }
}

// ============================================================================
// Re-Rack Formations
// ============================================================================

function canRerack(): boolean {
  const activeCount = ctx.cups.filter((c) => !c.isSunk).length;
  return (activeCount === 6 || activeCount === 3 || activeCount === 1) && !ctx.state.isReracked;
}

function executeRerack() {
  const activeCups = ctx.cups.filter((c) => !c.isSunk);
  const count = activeCups.length;

  if (count === 6) {
    // 6-Cup Triangle: Row 1 (1), Row 2 (2), Row 3 (3)
    ctx.state.rerackFormation = '6-triangle';
    let idx = 0;
    // Row 1
    activeCups[idx].relX = 0;
    activeCups[idx].relZ = -0.3;
    idx++;
    // Row 2
    activeCups[idx].relX = -0.5 * CUP_SPACING_X;
    activeCups[idx].relZ = -0.3 + CUP_SPACING_Z;
    idx++;
    activeCups[idx].relX = 0.5 * CUP_SPACING_X;
    activeCups[idx].relZ = -0.3 + CUP_SPACING_Z;
    idx++;
    // Row 3
    activeCups[idx].relX = -1.0 * CUP_SPACING_X;
    activeCups[idx].relZ = -0.3 + CUP_SPACING_Z * 2;
    idx++;
    activeCups[idx].relX = 0.0;
    activeCups[idx].relZ = -0.3 + CUP_SPACING_Z * 2;
    idx++;
    activeCups[idx].relX = 1.0 * CUP_SPACING_X;
    activeCups[idx].relZ = -0.3 + CUP_SPACING_Z * 2;
  } else if (count === 3) {
    // 3-Cup Triangle: Row 1 (1), Row 2 (2)
    ctx.state.rerackFormation = '3-triangle';
    let idx = 0;
    activeCups[idx].relX = 0;
    activeCups[idx].relZ = 0;
    idx++;
    activeCups[idx].relX = -0.5 * CUP_SPACING_X;
    activeCups[idx].relZ = CUP_SPACING_Z;
    idx++;
    activeCups[idx].relX = 0.5 * CUP_SPACING_X;
    activeCups[idx].relZ = CUP_SPACING_Z;
  } else if (count === 1) {
    // Single Island Cup in dead center
    ctx.state.rerackFormation = '1-center';
    activeCups[0].relX = 0;
    activeCups[0].relZ = 0.3;
  }

  // Update positions & animate smoothly
  positionTableAndCups(ctx.state.distanceYards);
  ctx.state.isReracked = true;

  playAudio('click');
  showEventToast('RE-RACK!', `${count}-Cup Triangle Formed`, 'READY TO SHOOT');
  updateHUD();
}

// ============================================================================
// Interactive Overhead Rack Minimap
// ============================================================================

function initRackMinimap() {
  ctx.rackCanvas = document.getElementById('rack-canvas') as HTMLCanvasElement;
  if (!ctx.rackCanvas) return;
  ctx.rackCtx = ctx.rackCanvas.getContext('2d') as CanvasRenderingContext2D;

  ctx.rackCanvas.addEventListener('click', (e) => {
    const rect = ctx.rackCanvas!.getBoundingClientRect();
    const clickX = e.clientX - rect.left;
    const clickY = e.clientY - rect.top;

    // Find clicked cup
    const w = ctx.rackCanvas!.width;
    const h = ctx.rackCanvas!.height;

    let closestCup: CupData | undefined;
    let minDist = 30 * 30; // click radius squared

    ctx.cups.forEach((cup) => {
      if (cup.isSunk) return;
      const cx = w / 2 + (cup.relX / 2.4) * (w / 2 - 25);
      const cy = 40 + ((cup.relZ + 0.8) / 3.8) * (h - 75);

      const d2 = (clickX - cx) ** 2 + (clickY - cy) ** 2;
      if (d2 < minDist) {
        minDist = d2;
        closestCup = cup;
      }
    });

    if (closestCup) {
      ctx.state.selectedCupId = closestCup.id;
      updateAimToSelectedCup();
      playAudio('click');
    }
  });
}

function drawRackMinimap() {
  if (!ctx.rackCtx || !ctx.rackCanvas) return;
  const c = ctx.rackCtx;
  const w = ctx.rackCanvas.width;
  const h = ctx.rackCanvas.height;

  c.clearRect(0, 0, w, h);

  // Draw Table boundary
  c.fillStyle = '#0f172a';
  c.strokeStyle = 'rgba(56, 189, 248, 0.4)';
  c.lineWidth = 2;
  c.beginPath();
  c.roundRect(14, 12, w - 28, h - 24, 10);
  c.fill();
  c.stroke();

  // Draw Table center line
  c.strokeStyle = 'rgba(245, 158, 11, 0.4)';
  c.lineWidth = 1.5;
  c.setLineDash([4, 4]);
  c.beginPath();
  c.moveTo(14, 28);
  c.lineTo(w - 14, 28);
  c.stroke();
  c.setLineDash([]);

  // Cup color based on target rack
  const isTargetBlue = (ctx.state.mode === 'versus' && ctx.state.activePlayerIndex === 0);
  const cupFillColor = isTargetBlue ? '#3b82f6' : '#ef4444';

  // Draw Cups
  ctx.cups.forEach((cup) => {
    const cx = w / 2 + (cup.relX / 2.4) * (w / 2 - 25);
    const cy = 40 + ((cup.relZ + 0.8) / 3.8) * (h - 75);
    const radius = 17;

    if (cup.isSunk) {
      // Sunk cup: subtle grey outline with red X
      c.fillStyle = 'rgba(15, 23, 42, 0.6)';
      c.strokeStyle = 'rgba(255, 255, 255, 0.1)';
      c.lineWidth = 1;
      c.beginPath();
      c.arc(cx, cy, radius, 0, Math.PI * 2);
      c.fill();
      c.stroke();

      // Red X
      c.strokeStyle = '#ef4444';
      c.lineWidth = 2;
      c.beginPath();
      c.moveTo(cx - 7, cy - 7);
      c.lineTo(cx + 7, cy + 7);
      c.moveTo(cx + 7, cy - 7);
      c.lineTo(cx - 7, cy + 7);
      c.stroke();
    } else {
      const isSelected = cup.id === ctx.state.selectedCupId;

      if (isSelected) {
        c.shadowColor = '#f59e0b';
        c.shadowBlur = 12;
      } else {
        c.shadowBlur = 0;
      }

      // Outer Cup Rim
      c.fillStyle = cupFillColor;
      c.beginPath();
      c.arc(cx, cy, radius, 0, Math.PI * 2);
      c.fill();

      // Inner Golden Beer
      c.fillStyle = '#d97706';
      c.beginPath();
      c.arc(cx, cy, radius - 3, 0, Math.PI * 2);
      c.fill();

      // White Foam highlight
      c.fillStyle = 'rgba(255, 251, 235, 0.7)';
      c.beginPath();
      c.arc(cx + 3, cy - 3, 4, 0, Math.PI * 2);
      c.fill();

      c.shadowBlur = 0;

      // Cup number
      c.fillStyle = '#ffffff';
      c.font = 'bold 10px sans-serif';
      c.textAlign = 'center';
      c.textBaseline = 'middle';
      c.fillText(`${cup.id}`, cx, cy);

      // Selected ring
      if (isSelected) {
        c.strokeStyle = '#f59e0b';
        c.lineWidth = 2.5;
        c.beginPath();
        c.arc(cx, cy, radius + 3, 0, Math.PI * 2);
        c.stroke();
      }
    }
  });
}

// ============================================================================
// Shot Detection & Sinking Logic (1 Cup Per Sink)
// ============================================================================

function checkBallCollisions() {
  if (!ctx.golfBall || !ctx.golfBall.isShotActive) return;

  const ballPos = ctx.golfBall.getPosition();
  // CRITICAL SAFETY: Ball must have traveled at least 5m from tee before cup collision can trigger
  if (ballPos.z < 5.0) return;

  const scale = getScaleForDistance(ctx.state.distanceYards);
  const tableTopY = TABLE_HEIGHT;
  const currentTableWidth = TABLE_WIDTH * scale;
  const currentTableLength = TABLE_LENGTH * Math.min(scale, 4.0);

  // 1. Runway Surface Contact / Bounce Detection:
  const relX = ballPos.x;
  const relZ = ballPos.z - ctx.tableCenterPos.z;

  if (
    !ctx.state.tableBouncedThisShot &&
    Math.abs(relX) <= currentTableWidth / 2 &&
    Math.abs(relZ) <= currentTableLength / 2 &&
    Math.abs(ballPos.y - tableTopY) <= 0.16 * Math.max(1, scale * 0.5)
  ) {
    ctx.state.tableBouncedThisShot = true;
    playAudio('table_bounce');
    console.log('[BeerPong] Ball made contact with tournament runway!');
  }

  // 2. Giant Flush Sunken Cup Roll-In / Swish Detection:
  const cupTopRadius = CUP_TOP_RADIUS * scale;
  for (const cup of ctx.cups) {
    if (cup.isSunk) continue;

    const dx = ballPos.x - cup.worldPos.x;
    const dz = ballPos.z - cup.worldPos.z;
    const distXZ = Math.sqrt(dx * dx + dz * dz);

    if (distXZ <= cupTopRadius && ballPos.y <= tableTopY + 0.38 * scale) {
      // Cup Rim Clink Check (near rim edge)
      if (Math.abs(distXZ - cupTopRadius) < 0.08 * scale && Math.abs(ballPos.y - tableTopY) < 0.14 * scale) {
        playAudio('cup_rim');
      }

      // Ball drops in / rolls in over the rim:
      if (distXZ < cupTopRadius - 0.02 * scale && ballPos.y <= tableTopY + 0.28 * scale) {
        handleCupSunk(cup, ctx.state.tableBouncedThisShot);
        break;
      }
    }
  }
}

function handleCupSunk(cup: CupData, wasBounceShot: boolean) {
  if (ctx.state.sunkThisShot) return;
  ctx.state.sunkThisShot = true;

  // Sinks ONLY this 1 cup
  cup.isSunk = true;
  ctx.state.totalSunk++;
  ctx.state.currentStreak++;
  if (ctx.state.currentStreak > ctx.state.bestStreak) {
    ctx.state.bestStreak = ctx.state.currentStreak;
  }

  const activePlayer = ctx.state.players[ctx.state.activePlayerIndex];
  activePlayer.cupsSunk++;

  const scale = getScaleForDistance(ctx.state.distanceYards);

  // Big Explosive 3D Splash & Expanding Shockwave Ring
  const splashOrigin = cup.worldPos.clone().setY(TABLE_HEIGHT + 0.02 * scale);
  ctx.particleSystem?.spawnBeerSplash(splashOrigin, 110, scale);

  // Pop cup scale and flash halo
  const meshRef = ctx.cupMeshes[cup.id - 1];
  if (meshRef?.cupMesh) {
    meshRef.cupMesh.scale.set(1.24, 1.24, 1.24);
  }

  // Camera impact trauma
  cameraTrauma = 0.12;

  // If on a streak or direct swish: shoot victory celebration fireworks!
  if (ctx.state.currentStreak >= 2 || !wasBounceShot) {
    ctx.particleSystem?.spawnCelebrationFireworks(splashOrigin, activePlayer.team, 180);
  }

  // Audio & Scoring
  playAudio('cup_sink');

  const basePts = getBasePointsForDistance(ctx.state.distanceYards);

  if (wasBounceShot) {
    ctx.state.bounceShots++;
    activePlayer.score += basePts;
    showEventToast(
      'RUNWAY ROLL-IN SINK!',
      `Cup #${cup.id} Eliminated!`,
      `+${basePts} PTS`
    );
  } else {
    // Direct swish bonus (+50% bonus points)
    const swishBonus = Math.round(basePts * 0.5);
    activePlayer.score += basePts + swishBonus;
    showEventToast(
      'DIRECT SWISH! 🎯',
      `Cup #${cup.id} Clean Swish!`,
      `+${basePts + swishBonus} PTS (BONUS)`
    );
  }

  // Play crowd cheer
  setTimeout(() => playAudio('cheer'), 180);

  // Check victory condition on active target rack
  const remainingCount = ctx.cups.filter((c) => !c.isSunk).length;
  if (remainingCount === 0) {
    handleVictory();
  } else {
    // Select next open cup as target
    updateAimToSelectedCup();
  }

  // Smooth ball plunge: Freeze physics, keep ball VISIBLE and animate it plunging into cup liquid
  if (ctx.golfBall) {
    ctx.golfBall.physics.freeze();
    ctx.golfBall.isShotActive = false;

    activeBallPlunge = {
      startPos: ctx.golfBall.object.position.clone(),
      targetPos: new THREE.Vector3(cup.worldPos.x, TABLE_HEIGHT - 0.02 * scale, cup.worldPos.z),
      progress: 0,
      scale: scale,
    };

    if (shotEndTimer) clearTimeout(shotEndTimer);
    shotEndTimer = setTimeout(() => {
      shotEndTimer = null;
      activeBallPlunge = null;
      handleShotEnd();
    }, 2400);
  }

  updateHUD();
}

let shotEndTimer: ReturnType<typeof setTimeout> | null = null;
let shotSafetyTimer: ReturnType<typeof setTimeout> | null = null;
let isHandlingShotEnd = false;

function handleShotEnd() {
  if (isHandlingShotEnd) return;
  isHandlingShotEnd = true;

  if (shotSafetyTimer) {
    clearTimeout(shotSafetyTimer);
    shotSafetyTimer = null;
  }

  if (shotEndTimer) {
    clearTimeout(shotEndTimer);
    shotEndTimer = null;
  }

  ctx.state.totalShots++;
  ctx.state.currentTurnShots++;

  if (!ctx.state.sunkThisShot) {
    // Miss / Airball
    ctx.state.currentStreak = 0;
    playAudio('airball');
    showEventToast('MISS!', 'No cup sank this shot', 'RESET FOR SHOT 2');
  }

  // Check turn progression
  if (ctx.state.currentTurnShots >= ctx.state.maxShotsPerTurn) {
    // Turn complete -> switch player in versus mode
    if (ctx.state.mode === 'versus') {
      ctx.state.activePlayerIndex = (ctx.state.activePlayerIndex + 1) % ctx.state.players.length;
      // Switch active target rack:
      // Player 1 (Red) shoots at blueRack; Player 2 (Blue) shoots at redRack
      ctx.cups = ctx.state.activePlayerIndex === 0 ? ctx.blueRack : ctx.redRack;
      positionTableAndCups(ctx.state.distanceYards);
      syncCupMeshesWithActiveRack();
      updateAimToSelectedCup();

      const nextPlayer = ctx.state.players[ctx.state.activePlayerIndex];
      const targetTeamName = nextPlayer.team === 'red' ? 'Blue' : 'Red';
      showEventToast('TURN SWITCH', `${nextPlayer.name}'s Turn! (${targetTeamName} Cups)`, 'GET READY');
    }
    ctx.state.currentTurnShots = 0;
  }

  // If a cup was sunk this shot, refresh table deck geometry to seal the sunken cup
  if (ctx.state.sunkThisShot) {
    positionTableAndCups(ctx.state.distanceYards);
  }

  // Reset shot flags
  ctx.state.tableBouncedThisShot = false;
  ctx.state.sunkThisShot = false;

  // Reset ball to tee and restore static camera view
  if (ctx.golfBall) {
    ctx.golfBall.isShotActive = false;
    ctx.golfBall.physics.freeze();
    ctx.golfBall.reset(ctx.aimPoint, ctx.startPoint);
  }

  if (ctx.camera) {
    ctx.camera.isTracking = false;
    ctx.camera.setPositions(ctx.startPoint, ctx.aimPoint);
  }

  // Re-aim at target
  updateAimToSelectedCup();
  updateHUD();

  setTimeout(() => {
    isHandlingShotEnd = false;
  }, 200);
}

function handleVictory() {
  ctx.state.isGameOver = true;
  playAudio('win');

  const winner = ctx.state.players[ctx.state.activePlayerIndex];
  const acc = ctx.state.totalShots > 0
    ? Math.round((ctx.state.totalSunk / ctx.state.totalShots) * 100)
    : 100;

  const modal = document.getElementById('modal-victory');
  const winnerEl = document.getElementById('v-winner-name');
  const shotsEl = document.getElementById('v-total-shots');
  const accEl = document.getElementById('v-accuracy');
  const bounceEl = document.getElementById('v-bounce-shots');

  if (winnerEl) winnerEl.textContent = winner.name;
  if (shotsEl) shotsEl.textContent = `${ctx.state.totalShots}`;
  if (accEl) accEl.textContent = `${acc}%`;
  if (bounceEl) bounceEl.textContent = `${ctx.state.bounceShots}`;
  if (modal) modal.style.display = 'flex';

  // Grand Victory Fireworks
  ctx.particleSystem?.spawnCelebrationFireworks(ctx.tableCenterPos, winner.team, 240);
  setTimeout(() => {
    ctx.particleSystem?.spawnCelebrationFireworks(ctx.tableCenterPos.clone().add(new THREE.Vector3(-3, 1, 0)), winner.team, 180);
    ctx.particleSystem?.spawnCelebrationFireworks(ctx.tableCenterPos.clone().add(new THREE.Vector3(3, 1, 0)), winner.team, 180);
  }, 450);
}

function resetGame() {
  ctx.state.isGameOver = false;
  ctx.state.totalShots = 0;
  ctx.state.totalSunk = 0;
  ctx.state.bounceShots = 0;
  ctx.state.currentStreak = 0;
  ctx.state.currentTurnShots = 0;
  ctx.state.isReracked = false;
  ctx.state.tableBouncedThisShot = false;
  ctx.state.sunkThisShot = false;

  ctx.state.players.forEach((p) => {
    p.cupsSunk = 0;
    p.score = 0;
  });

  const defaultPyramid = createPyramidLayout();

  // Reset both racks
  const resetRackData = (rack: CupData[]) => {
    rack.forEach((cup, idx) => {
      cup.isSunk = false;
      cup.sinkAnimProgress = 0;
      cup.relX = defaultPyramid[idx].relX;
      cup.relZ = defaultPyramid[idx].relZ;
    });
  };

  resetRackData(ctx.redRack);
  resetRackData(ctx.blueRack);

  // Active target rack: in versus mode Player 1 shoots at Blue rack
  ctx.cups = (ctx.state.mode === 'versus' && ctx.state.activePlayerIndex === 0)
    ? ctx.blueRack
    : ctx.redRack;

  // Restore 3D meshes
  const scale = getScaleForDistance(ctx.state.distanceYards);
  ctx.cupMeshes.forEach((meshRef, idx) => {
    const cup = ctx.cups[idx];
    cup.meshGroup = meshRef.group;
    cup.liquidMesh = meshRef.liquidMesh;
    cup.rimRingMesh = meshRef.rimRingMesh;
    cup.haloMesh = meshRef.haloMesh;

    meshRef.group.visible = true;
    meshRef.group.scale.set(scale, scale, scale);
    meshRef.liquidMesh.position.y = -0.07;
    (meshRef.rimRingMesh.material as THREE.MeshStandardMaterial).opacity = 1.0;
    (meshRef.haloMesh.material as THREE.MeshBasicMaterial).opacity = 0.0;
  });

  syncCupMeshesWithActiveRack();
  positionTableAndCups(ctx.state.distanceYards);

  const modal = document.getElementById('modal-victory');
  if (modal) modal.style.display = 'none';

  updateAimToSelectedCup();
  updateHUD();
}

