let toastTimeout: number | undefined;

function showEventToast(title: string, subtitle: string, badge: string) {
  const toast = document.getElementById('event-toast');
  const titleEl = document.getElementById('toast-title');
  const subEl = document.getElementById('toast-subtitle');
  const badgeEl = document.getElementById('toast-badge');

  if (toast && titleEl && subEl && badgeEl) {
    titleEl.textContent = title;
    subEl.textContent = subtitle;
    badgeEl.textContent = badge;

    toast.style.display = 'block';
    clearTimeout(toastTimeout);
    toastTimeout = window.setTimeout(() => {
      toast.style.display = 'none';
    }, 2400);
  }
}

function updateHUD() {
  // Turn card
  const activePlayer = ctx.state.players[ctx.state.activePlayerIndex];
  const playerNameEl = document.getElementById('player-name');
  const teamDotEl = document.getElementById('team-dot');
  if (playerNameEl) playerNameEl.textContent = activePlayer.name;
  if (teamDotEl) {
    teamDotEl.className = `team-dot ${activePlayer.team}`;
  }

  // Shot Pips
  const pip1 = document.getElementById('pip-1');
  const pip2 = document.getElementById('pip-2');
  if (pip1 && pip2) {
    pip1.className = ctx.state.currentTurnShots >= 1 ? 'shot-pip used' : 'shot-pip active';
    pip2.className = ctx.state.currentTurnShots >= 2 ? 'shot-pip used' : (ctx.state.currentTurnShots === 1 ? 'shot-pip active' : 'shot-pip');
  }

  // Cups Remaining Counter
  const remainingCount = ctx.cups.filter((c) => !c.isSunk).length;
  const countNumEl = document.getElementById('cups-left-count');
  if (countNumEl) countNumEl.textContent = `${remainingCount}`;

  // Streak badge
  const streakBadge = document.getElementById('streak-badge');
  if (streakBadge) {
    if (ctx.state.currentStreak >= 2) {
      streakBadge.style.display = 'inline-block';
      streakBadge.textContent = `🔥 STREAK: ${ctx.state.currentStreak}`;
    } else {
      streakBadge.style.display = 'none';
    }
  }

  // Re-Rack button status
  const btnRerack = document.getElementById('btn-rerack') as HTMLButtonElement;
  const rerackStatus = document.getElementById('rerack-status');
  if (btnRerack && rerackStatus) {
    if (canRerack()) {
      btnRerack.className = 'btn-rerack';
      btnRerack.disabled = false;
      rerackStatus.textContent = `${remainingCount} Cups: Triangle Re-Rack Available!`;
    } else {
      btnRerack.className = 'btn-rerack disabled';
      btnRerack.disabled = true;
      rerackStatus.textContent = ctx.state.isReracked
        ? 'Re-Rack Used This Game'
        : 'Re-Rack available at 6, 3, or 1 cup';
    }
  }

  // Scoreboard
  const p1 = ctx.state.players[0];
  const p2 = ctx.state.players[1];

  const redSunk = document.getElementById('team-red-sunk');
  const redPts = document.getElementById('team-red-pts');
  const blueSunk = document.getElementById('team-blue-sunk');
  const bluePts = document.getElementById('team-blue-pts');

  if (redSunk) redSunk.textContent = `${p1.cupsSunk}`;
  if (redPts) redPts.textContent = `${p1.score} pts`;
  if (blueSunk) blueSunk.textContent = `${p2.cupsSunk}`;
  if (bluePts) bluePts.textContent = `${p2.score} pts`;

  const redPlayerEl = document.getElementById('team-red-player');
  const bluePlayerEl = document.getElementById('team-blue-player');
  if (redPlayerEl && p1) redPlayerEl.textContent = p1.name;
  if (bluePlayerEl && p2) bluePlayerEl.textContent = p2.name;

  // Row active indicators
  const rowRed = document.getElementById('team-row-red');
  const rowBlue = document.getElementById('team-row-blue');
  if (rowRed && rowBlue) {
    rowRed.className = ctx.state.activePlayerIndex === 0 ? 'team-score-row active' : 'team-score-row';
    rowBlue.className = ctx.state.activePlayerIndex === 1 ? 'team-score-row active' : 'team-score-row';
  }

  // Stats grid
  const shotsTotalEl = document.getElementById('stat-shots-total');
  const accEl = document.getElementById('stat-accuracy');
  const bounceEl = document.getElementById('stat-bounces');
  const streakEl = document.getElementById('stat-best-streak');

  const accuracy = ctx.state.totalShots > 0
    ? Math.round((ctx.state.totalSunk / ctx.state.totalShots) * 100)
    : 0;

  if (shotsTotalEl) shotsTotalEl.textContent = `${ctx.state.totalShots}`;
  if (accEl) accEl.textContent = `${accuracy}%`;
  if (bounceEl) bounceEl.textContent = `${ctx.state.bounceShots}`;
  if (streakEl) streakEl.textContent = `${ctx.state.bestStreak}`;

  drawRackMinimap();
}

// ============================================================================
// Simulated Shot Launcher (Swish & Bounce calibrated shots)
// ============================================================================

function getCalibratedBeerPongSwish(distYards: number, targetCup?: CupData): OpenGolfSim.Shot {
  let baseSpeed = 27.6;
  let baseVla = 47.0;
  let baseSpin = 4400;

  const cupZ = targetCup ? targetCup.relZ : 0;

  if (distYards <= 15) {
    baseSpeed = 27.6 + cupZ * 0.75;
    baseVla = 47.0;
    baseSpin = 4400;
  } else if (distYards <= 30) {
    const t = (distYards - 15) / (30 - 15);
    baseSpeed = 27.8 + t * (39.5 - 27.8);
    baseVla = 44.0 + t * (43.0 - 44.0);
    baseSpin = 4200 + t * (5200 - 4200);
  } else if (distYards <= 60) {
    const t = (distYards - 30) / (60 - 30);
    baseSpeed = 39.5 + t * (58.6 - 39.5);
    baseVla = 43.0 + t * (40.0 - 43.0);
    baseSpin = 5200 + t * (6400 - 5200);
  } else if (distYards <= 100) {
    const t = (distYards - 60) / (100 - 60);
    baseSpeed = 58.6 + t * (82.5 - 58.6);
    baseVla = 40.0 + t * (35.0 - 40.0);
    baseSpin = 6400 + t * (6800 - 6400);
  } else if (distYards <= 150) {
    const t = (distYards - 100) / (150 - 100);
    baseSpeed = 82.5 + t * (114.4 - 82.5);
    baseVla = 35.0 + t * (30.0 - 35.0);
    baseSpin = 6800 + t * (5800 - 6800);
  } else {
    const t = Math.min(1.0, (distYards - 150) / (200 - 150));
    baseSpeed = 114.4 + t * (153.5 - 114.4);
    baseVla = 30.0 + t * (25.0 - 30.0);
    baseSpin = 5800 + t * (3200 - 5800);
  }

  return {
    ballSpeed: Math.round(baseSpeed * 10) / 10,
    verticalLaunchAngle: Math.round(baseVla * 10) / 10,
    horizontalLaunchAngle: 0,
    spinSpeed: baseSpin,
    totalSpin: baseSpin,
    spinAxis: 0,
    backSpin: Math.round(baseSpin * 0.98),
    sideSpin: 0,
  };
}

function getCalibratedBeerPongBounce(distYards: number): OpenGolfSim.Shot {
  let baseSpeed = 25.5;
  let baseVla = 24.0;
  let baseSpin = 3800;

  if (distYards <= 15) {
    baseSpeed = 25.5;
    baseVla = 24.0;
    baseSpin = 3800;
  } else if (distYards <= 30) {
    const t = (distYards - 15) / (30 - 15);
    baseSpeed = 25.5 + t * (36.0 - 25.5);
    baseVla = 24.0 + t * (26.0 - 24.0);
    baseSpin = 3800 + t * (4800 - 3800);
  } else if (distYards <= 60) {
    const t = (distYards - 30) / (60 - 30);
    baseSpeed = 36.0 + t * (52.0 - 36.0);
    baseVla = 26.0 + t * (28.0 - 26.0);
    baseSpin = 4800 + t * (5800 - 4800);
  } else if (distYards <= 100) {
    const t = (distYards - 60) / (100 - 60);
    baseSpeed = 52.0 + t * (72.0 - 52.0);
    baseVla = 28.0 + t * (24.0 - 28.0);
    baseSpin = 5800 + t * (6400 - 5800);
  } else if (distYards <= 150) {
    const t = (distYards - 100) / (150 - 100);
    baseSpeed = 72.0 + t * (95.0 - 72.0);
    baseVla = 24.0 + t * (18.0 - 24.0);
    baseSpin = 6400 + t * (5500 - 6400);
  } else {
    const t = Math.min(1.0, (distYards - 150) / (200 - 150));
    baseSpeed = 95.0 + t * (125.0 - 95.0);
    baseVla = 18.0 + t * (14.0 - 18.0);
    baseSpin = 5500 + t * (3000 - 5500);
  }

  return {
    ballSpeed: Math.round(baseSpeed * 10) / 10,
    verticalLaunchAngle: Math.round(baseVla * 10) / 10,
    horizontalLaunchAngle: 0,
    spinSpeed: baseSpin,
    totalSpin: baseSpin,
    spinAxis: 0,
    backSpin: Math.round(baseSpin * 0.95),
    sideSpin: 0,
  };
}

function executeShot(shot: OpenGolfSim.Shot) {
  if (!ctx.golfBall) return;

  // Clear any pending celebration / shot end timers
  if (shotEndTimer) {
    clearTimeout(shotEndTimer);
    shotEndTimer = null;
  }
  if (shotSafetyTimer) {
    clearTimeout(shotSafetyTimer);
    shotSafetyTimer = null;
  }
  isHandlingShotEnd = false;
  ctx.state.sunkThisShot = false;
  ctx.state.tableBouncedThisShot = false;
  activeBallPlunge = null;

  // Ensure golfBall is completely unlocked and ready
  ctx.golfBall.isShotActive = false;

  // Turn off table closeup cam if active so player watches ball flight
  if (ctx.state.isTableCam) {
    ctx.state.isTableCam = false;
  }

  // Reset ball to tee, aiming at target
  ctx.golfBall.reset(ctx.aimPoint, ctx.startPoint);
  ctx.golfBall.aimAt(ctx.aimPoint);

  playAudio('hit');

  if (ctx.camera) {
    ctx.camera.isTracking = true;
  }

  ctx.golfBall.launchShot(shot);

  // Safety fallback: if ball gets lost or physics fails to ground after 9.5s, force shot end
  shotSafetyTimer = setTimeout(() => {
    shotSafetyTimer = null;
    if (ctx.golfBall?.isShotActive) {
      console.log('[BeerPong] Shot safety timeout reached, forcing shot end');
      handleShotEnd();
    }
  }, 9500);
}

function launchSimulatedSwish() {
  updateAimToSelectedCup();
  const targetCup = ctx.cups.find(c => c.id === ctx.state.selectedCupId);
  const shot = getCalibratedBeerPongSwish(ctx.state.distanceYards, targetCup);
  console.log(`[BeerPong] Launching SWISH: ${shot.ballSpeed} mph, VLA ${shot.verticalLaunchAngle} deg`);
  executeShot(shot);
}

function launchSimulatedBounce() {
  updateAimToSelectedCup();
  const shot = getCalibratedBeerPongBounce(ctx.state.distanceYards);
  console.log(`[BeerPong] Launching BOUNCE: ${shot.ballSpeed} mph, VLA ${shot.verticalLaunchAngle} deg`);
  executeShot(shot);
}

function launchSimulatedShot() {
  launchSimulatedSwish();
}

// ============================================================================
// Main Initialization & Game Loop
// ============================================================================

async function setupGame() {
  ctx.timer.connect(document);

  const canvas = document.getElementById('canvas');
  if (!canvas || !(canvas instanceof HTMLCanvasElement)) {
    throw new Error('Canvas element missing or invalid');
  }

  // Determine initial graphics quality (URL param -> localStorage -> setupData -> default Epic)
  let initialQuality = QualityMode.Epic;
  try {
    const urlParams = new URLSearchParams(window.location.search);
    const qParam = urlParams.get('quality');
    const storedQ = typeof localStorage !== 'undefined' ? localStorage.getItem('ogs_graphics_quality') : null;
    initialQuality = parseQuality(qParam || storedQ || ctx.setupData?.qualityLevel || 'epic');
  } catch (e) {
    initialQuality = QualityMode.Epic;
  }
  ctx.currentQuality = initialQuality;

  // 1. Renderer
  ctx.renderer = new FuseRenderer({
    canvas,
    adaptive: true,
    renderMode: 'webgpu',
    forceWebGL: ctx.setupData?.backend === 'webgl',
    qualityLevel: initialQuality,
  });
  await ctx.renderer.init();

  // 2. Environment & Terrain
  const { ground } = createBeerPongEnvironment(ctx.scene);
  ctx.groundMesh = ground;

  // 3. Camera
  ctx.camera = new ShotPerspectiveCamera({
    scene: ground,
    far: 1800,
    autoPosition: true,
    cameraOffsetX: 0,
  });
  ctx.camera.setPositions(ctx.startPoint, ctx.aimPoint);

  // Setup Post-Processing (Bloom glow & tone mapping on High/Epic)
  ctx.renderer.setupPostProcessing(ctx.scene, ctx.camera);

  // AAA Dynamic Lighting & Particle VFX
  ctx.ballLight = new THREE.PointLight(0xf59e0b, 0, 18, 1.8);
  ctx.scene.add(ctx.ballLight);
  ctx.particleSystem = new ArcadeParticleSystem(ctx.scene, 1400);

  // 4. Procedural Beer Pong Table & Cups
  const { tableGroup, tableTop, tableRamp, borders, centerLine, legsGroup } = buildBeerPongTable();
  ctx.tableGroup = tableGroup;
  ctx.tableTopMesh = tableTop;
  ctx.tableRampMesh = tableRamp;
  ctx.tableBorders = borders;
  ctx.tableCenterLine = centerLine;
  ctx.tableLegsGroup = legsGroup;
  ctx.scene.add(tableGroup);

  // Initialize Red and Blue cup racks
  ctx.redRack = createPyramidLayout();
  ctx.blueRack = createPyramidLayout();
  ctx.cups = ctx.redRack; // initially active

  // Setup players from launcher setupData if provided
  if (ctx.setupData?.players && ctx.setupData.players.length > 0) {
    const launcherPlayers = ctx.setupData.players;
    if (launcherPlayers.length === 1) {
      ctx.state.players = [
        { name: launcherPlayers[0].name || 'Player 1', team: 'red', cupsSunk: 0, score: 0 },
        { name: 'Player 2', team: 'blue', cupsSunk: 0, score: 0 },
      ];
    } else {
      ctx.state.players = launcherPlayers.map((lp, idx) => ({
        name: lp.name || `Player ${idx + 1}`,
        team: (idx % 2 === 0 ? 'red' : 'blue') as 'red' | 'blue',
        cupsSunk: 0,
        score: 0,
      }));
    }
  }

  // Initialize 10 Cup 3D Meshes on table
  ctx.cupMeshes = [];
  for (let i = 0; i < 10; i++) {
    const meshRef = buildSoloCupMesh('red');
    ctx.cupMeshes.push(meshRef);
    tableGroup.add(meshRef.group);
  }

  syncCupMeshesWithActiveRack();
  positionTableAndCups(ctx.state.distanceYards);

  // 5. Particle System
  initParticleSystem(ctx.scene);

  // 6. Golf Ball & Aerodynamics
  ctx.golfBall = new GolfBall(ctx.scene, {
    setupData: ctx.setupData || {},
    groundMeshes: [ground, tableTop, tableRamp],
    stimpLevel: 8,
  });
  ctx.golfBall.reset(ctx.aimPoint, ctx.startPoint);

  ctx.golfBall.on('shotEnded', () => {
    ctx.camera?.setTracking(false);
    ctx.camera?.setPositions(ctx.startPoint, ctx.aimPoint);
    handleShotEnd();
  });

  // 7. Interactive Rack Minimap & UI Listeners
  initRackMinimap();
  setupUIEventListeners();

  updateAimToSelectedCup();
  updateHUD();
}

// Aim Keys State
const aimKeys = { left: false, right: false };

function setupUIEventListeners() {
  // Distance buttons (15, 30, 60, 100, 150, 200 Yards)
  [15, 30, 60, 100, 150, 200].forEach((dist) => {
    const btn = document.getElementById(`dist-${dist}`);
    if (btn) {
      btn.addEventListener('click', () => {
        document.querySelectorAll('.dist-btn').forEach((b) => b.classList.remove('active'));
        btn.classList.add('active');

        ctx.state.distanceYards = dist;
        const displayEl = document.getElementById('target-dist-display');
        const clubEl = document.getElementById('target-club-display');
        if (displayEl) displayEl.textContent = `${dist}`;
        if (clubEl) clubEl.textContent = getClubNameForDistance(dist);

        positionTableAndCups(dist);
        playAudio('click');
        updateHUD();
      });
    }
  });

  // Re-Rack button
  const btnRerack = document.getElementById('btn-rerack');
  if (btnRerack) {
    btnRerack.addEventListener('click', () => {
      if (canRerack()) executeRerack();
    });
  }

  // Simulated Hit Buttons
  const btnHitSim = document.getElementById('btn-sim-hit');
  if (btnHitSim) {
    btnHitSim.addEventListener('click', () => launchSimulatedSwish());
  }

  const btnSimSwish = document.getElementById('btn-sim-swish');
  if (btnSimSwish) {
    btnSimSwish.addEventListener('click', () => launchSimulatedSwish());
  }

  const btnSimBounce = document.getElementById('btn-sim-bounce');
  if (btnSimBounce) {
    btnSimBounce.addEventListener('click', () => launchSimulatedBounce());
  }

  // Table Cam Button
  const btnTableCam = document.getElementById('btn-table-cam');
  if (btnTableCam) {
    btnTableCam.addEventListener('click', toggleTableCam);
  }

  // Center Aim Button
  const btnCenterAim = document.getElementById('btn-center-aim');
  if (btnCenterAim) {
    btnCenterAim.addEventListener('click', () => {
      ctx.state.aimAngleDeg = 0;
      updateAimToSelectedCup();
      playAudio('click');
    });
  }

  // Audio Toggle Button
  const btnAudio = document.getElementById('btn-audio-toggle');
  if (btnAudio) {
    btnAudio.addEventListener('click', () => {
      ctx.audioMuted = !ctx.audioMuted;
      btnAudio.textContent = ctx.audioMuted ? '\uD83D\uDD07' : '\uD83D\uDD0A';
    });
  }

  // Mode Toggle Button (Solo vs Versus)
  const btnMode = document.getElementById('btn-toggle-mode');
  if (btnMode) {
    btnMode.addEventListener('click', () => {
      ctx.state.mode = ctx.state.mode === 'solo' ? 'versus' : 'solo';
      btnMode.textContent = `Mode: ${ctx.state.mode === 'solo' ? 'Solo' : '2-Player'}`;
      const modeBadge = document.getElementById('mode-badge');
      if (modeBadge) modeBadge.textContent = ctx.state.mode === 'solo' ? 'SOLO PRACTICE' : '2-PLAYER VERSUS';

      // In versus mode: Player 1 shoots at Blue cups
      ctx.cups = (ctx.state.mode === 'versus' && ctx.state.activePlayerIndex === 0)
        ? ctx.blueRack
        : ctx.redRack;
      positionTableAndCups(ctx.state.distanceYards);
      syncCupMeshesWithActiveRack();
      updateAimToSelectedCup();

      playAudio('click');
      updateHUD();
    });
  }

  // Reset Game Button
  const btnReset = document.getElementById('btn-reset-game');
  if (btnReset) {
    btnReset.addEventListener('click', () => {
      resetGame();
      playAudio('click');
    });
  }

  // Victory Modal Buttons
  const btnPlayAgain = document.getElementById('btn-play-again');
  if (btnPlayAgain) {
    btnPlayAgain.addEventListener('click', () => resetGame());
  }

  const btnNextDist = document.getElementById('btn-next-dist');
  if (btnNextDist) {
    btnNextDist.addEventListener('click', () => {
      const order = [15, 30, 60, 100, 150, 200];
      const curIdx = order.indexOf(ctx.state.distanceYards);
      const nextDist = order[(curIdx + 1) % order.length];
      const distBtn = document.getElementById(`dist-${nextDist}`);
      if (distBtn) distBtn.click();
      resetGame();
    });
  }

  // Graphics Quality Selector Buttons
  const qualityMap: Record<string, QualityMode> = {
    low: QualityMode.Low,
    medium: QualityMode.Medium,
    high: QualityMode.High,
    epic: QualityMode.Epic,
  };
  document.querySelectorAll('.q-btn').forEach((btn) => {
    btn.addEventListener('click', () => {
      const qKey = btn.getAttribute('data-quality');
      if (qKey && qualityMap[qKey] !== undefined) {
        setGraphicsQuality(qualityMap[qKey]);
        playAudio('click');
      }
    });
  });
  updateQualityUI(ctx.currentQuality);
}

function setGraphicsQuality(level: QualityMode) {
  ctx.currentQuality = level;
  if (ctx.renderer && ctx.camera) {
    ctx.renderer.setQualityLevel(level, ctx.scene, ctx.camera);
  }
  try {
    localStorage.setItem('ogs_graphics_quality', qualityToString(level));
  } catch (e) {}
  updateQualityUI(level);

  // Dynamic feature toggling
  if (ctx.dirLight) {
    ctx.dirLight.castShadow = level > QualityMode.Low;
    if (level === QualityMode.Medium) {
      ctx.dirLight.shadow.mapSize.set(1024, 1024);
    } else if (level === QualityMode.High) {
      ctx.dirLight.shadow.mapSize.set(2048, 2048);
    } else if (level >= QualityMode.VeryHigh) {
      ctx.dirLight.shadow.mapSize.set(4096, 4096);
    }
    ctx.dirLight.shadow.map?.dispose();
    (ctx.dirLight.shadow as any).map = null;
  }

  // Volumetric floodlight beams
  ctx.volumetricBeams.forEach((beam) => {
    beam.visible = level > QualityMode.Low;
    if (beam.material instanceof THREE.ShaderMaterial) {
      const alpha = level >= QualityMode.VeryHigh ? 0.22 : level === QualityMode.High ? 0.16 : 0.08;
      beam.material.uniforms.intensity.value = alpha;
    }
  });

  // Table reflectivity
  if (ctx.tableTopMesh && ctx.tableTopMesh.material instanceof THREE.MeshStandardMaterial) {
    ctx.tableTopMesh.material.roughness = level >= QualityMode.High ? 0.12 : 0.25;
  }
}

function updateQualityUI(level: QualityMode) {
  const str = qualityToString(level);
  document.querySelectorAll('.q-btn').forEach((b) => {
    const q = b.getAttribute('data-quality');
    if (q === str) {
      b.classList.add('active');
    } else {
      b.classList.remove('active');
    }
  });

  // Cup Cycling and Target Selection
  function cycleTargetCup(step: number) {
    const activeCups = ctx.cups.filter((c) => !c.isSunk);
    if (activeCups.length <= 1) return;
    const curIdx = activeCups.findIndex((c) => c.id === ctx.state.selectedCupId);
    const nextIdx = (curIdx + step + activeCups.length) % activeCups.length;
    ctx.state.selectedCupId = activeCups[nextIdx].id;
    ctx.state.aimAngleDeg = 0;
    updateAimToSelectedCup();
    playAudio('click');
  }

  // 3D Canvas Click-to-Target Raycasting
  const canvasEl = document.getElementById('canvas');
  if (canvasEl) {
    const raycaster = new THREE.Raycaster();
    const mousePos = new THREE.Vector2();

    canvasEl.addEventListener('pointerdown', (e) => {
      if (ctx.golfBall?.isShotActive || !ctx.camera || ctx.state.isTableCam) return;
      const rect = canvasEl.getBoundingClientRect();
      mousePos.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
      mousePos.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
      raycaster.setFromCamera(mousePos, ctx.camera);
      const cupGroups = ctx.cupMeshes.map((m) => m.group);
      const hits = raycaster.intersectObjects(cupGroups, true);
      if (hits.length > 0) {
        let obj: THREE.Object3D | null = hits[0].object;
        while (obj && obj.parent && !obj.userData?.cupId) {
          obj = obj.parent;
        }
        if (obj?.userData?.cupId) {
          const cup = ctx.cups.find((c) => c.id === obj!.userData.cupId && !c.isSunk);
          if (cup) {
            ctx.state.selectedCupId = cup.id;
            ctx.state.aimAngleDeg = 0;
            updateAimToSelectedCup();
            playAudio('click');
          }
        }
      }
    });
  }

  // Global Keyboard Controls
  window.addEventListener('keydown', (e) => {
    if (e.code === 'Space') {
      e.preventDefault();
      launchSimulatedSwish();
    } else if (e.code === 'KeyB') {
      e.preventDefault();
      launchSimulatedBounce();
    } else if (e.code === 'KeyC') {
      toggleTableCam();
    } else if (e.code === 'KeyR') {
      if (canRerack()) executeRerack();
    } else if (e.code === 'KeyM') {
      ctx.audioMuted = !ctx.audioMuted;
      const bAudio = document.getElementById('btn-audio-toggle');
      if (bAudio) bAudio.textContent = ctx.audioMuted ? '\uD83D\uDD07' : '\uD83D\uDD0A';
    } else if (e.code === 'Digit1') {
      document.getElementById('dist-15')?.click();
    } else if (e.code === 'Digit2') {
      document.getElementById('dist-30')?.click();
    } else if (e.code === 'Digit3') {
      document.getElementById('dist-60')?.click();
    } else if (e.code === 'Digit4') {
      document.getElementById('dist-100')?.click();
    } else if (e.code === 'Digit5') {
      document.getElementById('dist-150')?.click();
    } else if (e.code === 'Digit6') {
      document.getElementById('dist-200')?.click();
    } else if (e.code === 'ArrowLeft') {
      aimKeys.left = true;
      e.preventDefault();
    } else if (e.code === 'ArrowRight') {
      aimKeys.right = true;
      e.preventDefault();
    } else if (e.code === 'KeyA' || e.code === 'ArrowUp') {
      cycleTargetCup(-1);
      e.preventDefault();
    } else if (e.code === 'KeyD' || e.code === 'ArrowDown') {
      cycleTargetCup(1);
      e.preventDefault();
    }
  });

  window.addEventListener('keyup', (e) => {
    if (e.code === 'ArrowLeft') {
      aimKeys.left = false;
    } else if (e.code === 'ArrowRight') {
      aimKeys.right = false;
    }
  });
}

function toggleTableCam() {
  ctx.state.isTableCam = !ctx.state.isTableCam;
  playAudio('click');
}

// ============================================================================
// Animate Loop
// ============================================================================

function animate(animDelta: number) {
  requestAnimationFrame(animate);

  ctx.timer.update(animDelta);
  const rawDelta = ctx.timer.getDelta();
  const delta = Math.max(0.001, Math.min(rawDelta > 0.0001 ? rawDelta : 0.016, 0.1));

  // 1. Update Golf Ball Physics & Camera
  if (ctx.golfBall && ctx.camera) {
    ctx.golfBall.update(delta);

    const ballPos = ctx.golfBall.object?.position;
    if (
      (ctx.golfBall.isShotActive || ctx.state.sunkThisShot) &&
      ballPos &&
      !isNaN(ballPos.x) &&
      !isNaN(ballPos.y) &&
      !isNaN(ballPos.z)
    ) {
      ctx.camera.track(delta, ctx.startPoint, ballPos);
      if (ctx.golfBall.isShotActive) {
        checkBallCollisions();
      }
    } else if (ctx.state.isTableCam) {
      // Zoomed elevated view scaled to distance
      const scale = getScaleForDistance(ctx.state.distanceYards);
      const targetZ = ctx.tableCenterPos.z;
      const targetCamPos = new THREE.Vector3(0, TABLE_HEIGHT + 2.5 * scale, targetZ - 8.5 * scale);
      ctx.camera.position.lerp(targetCamPos, delta * 3.5);
      ctx.camera.lookAt(0, TABLE_HEIGHT + 0.2, targetZ + 1.0 * scale);
    } else {
      if (!ctx.golfBall.isShotActive && !ctx.state.isTableCam) {
        if (aimKeys.left) {
          ctx.state.aimAngleDeg = Math.max(ctx.state.aimAngleDeg - 8.0 * delta, -20);
          updateAimToSelectedCup();
        } else if (aimKeys.right) {
          ctx.state.aimAngleDeg = Math.min(ctx.state.aimAngleDeg + 8.0 * delta, 20);
          updateAimToSelectedCup();
        }
      }
      ctx.camera.update(delta, ctx.startPoint, ctx.aimPoint);
      if (!ctx.golfBall.isShotActive) {
        ctx.golfBall.aimAt(ctx.aimPoint);
      }
    }
  }

  // 2. Animate Sunk Cups & Ball Plunge Physics
  if (activeBallPlunge && ctx.golfBall) {
    activeBallPlunge.progress = Math.min(activeBallPlunge.progress + delta * 2.8, 1.0);
    const p = activeBallPlunge.progress;
    const curX = THREE.MathUtils.lerp(activeBallPlunge.startPos.x, activeBallPlunge.targetPos.x, Math.pow(p, 0.65));
    const curZ = THREE.MathUtils.lerp(activeBallPlunge.startPos.z, activeBallPlunge.targetPos.z, Math.pow(p, 0.65));
    const curY = THREE.MathUtils.lerp(activeBallPlunge.startPos.y, activeBallPlunge.targetPos.y, Math.pow(p, 0.6));
    const bob = p >= 0.75 ? Math.sin((p - 0.75) * 16) * 0.012 * activeBallPlunge.scale : 0;
    ctx.golfBall.object.position.set(curX, curY + bob, curZ);
  }

  // Restore cup scale smoothly after sink pop
  ctx.cups.forEach((cup, idx) => {
    const meshRef = ctx.cupMeshes[idx];
    if (meshRef?.cupMesh) {
      meshRef.cupMesh.scale.lerp(new THREE.Vector3(1, 1, 1), delta * 6.0);
    }
    // Fade liquid inside sunk cup without hiding the cup body
    if (cup.isSunk && meshRef && cup.sinkAnimProgress < 1.0) {
      cup.sinkAnimProgress = Math.min(cup.sinkAnimProgress + delta * 1.5, 1.0);
      meshRef.liquidMesh.position.y = -0.07 - cup.sinkAnimProgress * 0.25;
      (meshRef.rimRingMesh.material as THREE.MeshStandardMaterial).opacity = Math.max(0, 1 - cup.sinkAnimProgress * 1.2);
    }
  });

  // Apply subtle camera trauma punch on sink
  if (cameraTrauma > 0 && ctx.camera) {
    ctx.camera.position.x += (Math.random() - 0.5) * cameraTrauma;
    ctx.camera.position.y += (Math.random() - 0.5) * cameraTrauma;
    cameraTrauma = Math.max(0, cameraTrauma - delta * 0.85);
  }

  // 3. Subtle Target Aura Rotation & Pulsing
  const time = Date.now() * 0.001;
  ctx.cups.forEach((cup, idx) => {
    const meshRef = ctx.cupMeshes[idx];
    if (!cup.isSunk && meshRef?.haloMesh && cup.id === ctx.state.selectedCupId) {
      meshRef.haloMesh.rotation.z = time * 0.5;
      const pulse = 0.55 + Math.sin(time * 3) * 0.25;
      meshRef.haloMesh.material.opacity = pulse;
    }
  });

  // 4. Update Splash Particles & AAA Particle System
  updateSplashParticles(delta);
  if (ctx.particleSystem) {
    ctx.particleSystem.update(delta);
  }

  // 5. Dynamic Beer Liquid Ripples & Surface Shimmer (Medium+)
  if (ctx.currentQuality >= QualityMode.Medium && ctx.liquidMaterials.length > 0) {
    const t = performance.now() * 0.0025;
    ctx.liquidMaterials.forEach((mat) => {
      mat.roughness = 0.08 + Math.sin(t) * 0.02;
      mat.emissiveIntensity = 0.42 + Math.cos(t * 1.6) * 0.08;
    });
  }

  // 6. Dynamic Ball Light Aura
  if (ctx.ballLight && ctx.golfBall) {
    const ballPos = ctx.golfBall.object?.position;
    if (ctx.golfBall.isShotActive && ballPos) {
      ctx.ballLight.position.copy(ballPos);
      ctx.ballLight.intensity = ctx.currentQuality >= QualityMode.High ? 2.5 : 1.2;
    } else {
      ctx.ballLight.intensity = 0;
    }
  }

  // 7. Render Scene
  if (ctx.renderer && ctx.camera) {
    ctx.renderer.render(ctx.scene, ctx.camera, ctx.scene.fog);
  }
}

// ============================================================================
// Lifecycle & Handshake
// ============================================================================

function preLoad() {
  ctx.loadingScreen = new UILoadingScreen(document.body, { loadingPrefix: 'Preparing Beer Pong' });
  ctx.loadingScreen.on('load', () => {
    requestAnimationFrame(animate);
    ctx.renderer?.startAdaptiveResolution();
    app.setLoaded();
  });
  ctx.loadingScreen.load(setupGame);
  document.body.style.opacity = '1';
}

function initializeDebug() {
  ctx.setupData = generateSetupData(2);
  preLoad();
}

function initializeSetup(payload: any) {
  if (!payload?.setupData) throw new Error('No setupData received');
  ctx.setupData = payload.setupData as OpenGolfSim.SetupData;
  preLoad();
}

// AppBridge Handshake
app.initialize(() => {
  if (app.appType === 'web') {
    initializeDebug();
  }
});

app.on('setup', initializeSetup);
app.on('shot', (shot: OpenGolfSim.Shot) => {
  updateAimToSelectedCup();
  const spin = Number(shot.spinSpeed ?? (shot as any).totalSpin ?? 5000);
  shot.spinSpeed = isNaN(spin) || spin <= 0 ? 5000 : spin;
  shot.ballSpeed = Math.max(1, Number(shot.ballSpeed) || 30);
  executeShot(shot);
});
